<?php require __DIR__.'/bootstrap.php'; require __DIR__.'/layout.php'; $u=require_login();
$scope=$u['role']==='ADMIN'?'1=1':'creado_por_id='.(int)$u['id'];
$stats=$db->query("SELECT COUNT(*) total, SUM(DATE(created_at)=CURDATE()) hoy, SUM(YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())) mes, COALESCE(SUM(IF(YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE()),monto_acordado,0)),0) monto, SUM(estado='PENDIENTE_APROBACION') pendientes, SUM(estado='VIGENTE') vigentes, SUM(estado='CUMPLIDO') cumplidos, SUM(estado='INCUMPLIDO') incumplidos FROM acuerdos WHERE $scope")->fetch(); page_start($u['role']==='ADMIN'?'Dashboard administrativo':'Mi dashboard',$u); ?>
<section class="welcome"><h2>Bienvenido, <?=e($u['username'])?></h2><p>Rol: <?=e(ucfirst(strtolower($u['role'])))?></p></section><section class="cards"><?php foreach(['Acuerdos hoy'=>'hoy','Acuerdos del mes'=>'mes','Monto acordado'=>'monto','Pendientes'=>'pendientes','Vigentes'=>'vigentes','Cumplidos'=>'cumplidos','Incumplidos'=>'incumplidos'] as $label=>$key):?><article><span><?=e($label)?></span><strong><?=$key==='monto'?money($stats[$key]):(int)$stats[$key]?></strong></article><?php endforeach?></section><section class="actions"><a class="primary" href="<?=url('clientes.php')?>">Buscar cliente</a><a class="secondary" href="<?=url('acuerdos.php')?>">Consultar acuerdos</a></section>
<?php if($u['role']==='ADMIN'):$rows=$db->query("SELECT u.username,COUNT(a.id) acuerdos,SUM(a.tipo_acuerdo='CANCELACION') cancelaciones,SUM(a.tipo_acuerdo='CONVENIO') convenios,COALESCE(SUM(a.monto_acordado),0) monto FROM usuarios u LEFT JOIN acuerdos a ON a.creado_por_id=u.id GROUP BY u.id ORDER BY u.username")->fetchAll();?><section class="panel"><h2>Acuerdos por agente</h2><table><thead><tr><th>Agente</th><th>Acuerdos</th><th>Cancelaciones</th><th>Convenios</th><th>Monto</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=(int)$r['acuerdos']?></td><td><?=(int)$r['cancelaciones']?></td><td><?=(int)$r['convenios']?></td><td><?=money($r['monto'])?></td></tr><?php endforeach?></tbody></table></section><?php endif; page_end();

